def admit(active, waiting, budget, slots):
    active_total = sum(active)

    # Oversized reservations can never fit: reject outright.
    for value in waiting:
        if value > budget:
            raise ValueError("waiting reservation exceeds budget")

    admitted = []
    remaining = []
    stopped = False
    running = active_total

    for value in waiting:
        if stopped:
            remaining.append(value)
            continue
        fits_slots = len(admitted) + len(active) < slots
        if fits_slots and running + value <= budget:
            admitted.append(value)
            running += value
        else:
            stopped = True
            remaining.append(value)

    return admitted, remaining

def endpoint(base_url, path):
    base = base_url.rstrip('/')
    segments = base.split('/')
    if segments and segments[-1] == 'v1':
        segments.pop()
    base = '/'.join(segments)
    return base + '/v1/' + path.lstrip('/')

