def admit(active, waiting, budget, slots):
    # Any waiting reservation that alone exceeds the total budget is invalid,
    # even if FIFO order would never have reached it.
    for value in waiting:
        if value > budget:
            raise ValueError("waiting reservation exceeds the total budget")

    admitted = []
    running = sum(active)

    # FIFO: admit while the reservation fits the budget and there is a free slot.
    for value in waiting:
        if running + value > budget:
            break
        if len(admitted) + len(active) >= slots:
            break
        admitted.append(value)
        running += value

    remaining = waiting[len(admitted):]
    return admitted, remaining
